#pragma once

// Dataset access and the list of datasets the benchmark runs on.
//
// The datasets are generated by benchmark/scripts/MakeClusteringDatasets.py into
// benchmark/bin/datasets/. They are not tracked: see benchmark/README.md.

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace ffcl::benchmark {

namespace fs = std::filesystem;

// Root of the repository, resolved from the executable's location (the benchmark is built into
// <repo>/build*/), so the benchmark works from any working directory.
inline auto repository_root() -> fs::path& {
    static auto root = fs::path{".."};
    return root;
}

inline void set_repository_root_from_executable(const std::string& executable_path) {
    // weakly_canonical removes the "./" that argv[0] usually carries, otherwise the second
    // parent_path() would not pop a directory
    const auto executable_directory =
        fs::weakly_canonical(fs::absolute(executable_path)).parent_path();

    repository_root() = executable_directory.parent_path();
}

inline auto datasets_root() -> fs::path {
    return repository_root() / "benchmark" / "bin" / "datasets" / "inputs";
}

inline auto results_root() -> fs::path {
    return repository_root() / "benchmark" / "bin" / "results";
}

struct Dataset {
    std::string        name;
    std::vector<float> data;
    std::size_t        n_features = 0;
    std::size_t        n_samples  = 0;
};

inline auto num_features_in_file(const fs::path& filepath, char delimiter = ' ') -> std::size_t {
    std::ifstream file(filepath);

    if (!file.is_open()) {
        throw std::runtime_error("Cannot open '" + filepath.string() +
                                 "'. Generate the datasets first: python3 benchmark/scripts/MakeClusteringDatasets.py");
    }
    std::string line;

    std::getline(file, line);

    return static_cast<std::size_t>(std::count(line.begin(), line.end(), delimiter)) + 1;
}

inline auto load_dataset_from_path(const std::string& filepath, std::size_t n_features) -> Dataset {
    auto       data        = std::vector<float>{};
    std::ifstream filestream(filepath);
    std::string   row_str, element_str;

    if (!filestream.is_open()) {
        throw std::runtime_error("Cannot open '" + filepath + "'");
    }
    while (std::getline(filestream, row_str, '\n')) {
        std::stringstream row_stream(row_str);

        while (std::getline(row_stream, element_str, ' ')) {
            if (!element_str.empty()) {
                data.emplace_back(std::stof(element_str));
            }
        }
    }
    const auto n_samples = data.size() / n_features;

    return Dataset{fs::path(filepath).stem().string(), std::move(data), n_features, n_samples};
}

inline auto load_dataset(const std::string& name) -> Dataset {
    const auto filepath = datasets_root() / (name + ".txt");

    const auto n_features = num_features_in_file(filepath);

    auto       data        = std::vector<float>{};
    std::ifstream filestream(filepath);
    std::string   row_str, element_str;

    while (std::getline(filestream, row_str, '\n')) {
        std::stringstream row_stream(row_str);

        while (std::getline(row_stream, element_str, ' ')) {
            if (!element_str.empty()) {
                data.emplace_back(std::stof(element_str));
            }
        }
    }
    // n_samples has to be computed before the move, otherwise it reads the emptied vector
    const auto n_samples = data.size() / n_features;

    return Dataset{name, std::move(data), n_features, n_samples};
}

// The datasets generated by the script, in the order the tables use.
inline auto all_dataset_names() -> const std::vector<std::string>& {
    static const auto names = std::vector<std::string>{
        "noisy_circles", "noisy_moons", "varied", "aniso", "blobs", "no_structure", "unbalanced_blobs"};
    return names;
}

// One reference leaf size for every dataset and every library, as agreed: each library at its own
// best known leaf size, but not tuned per dataset.
inline constexpr std::size_t kFFCLLeafSize = 0;  // 0 means sqrt(n) / 3, resolved per dataset
inline constexpr std::size_t kReferenceLeafSize = 40;

inline auto ffcl_leaf_size_for(std::size_t n_samples) -> std::size_t {
    return std::max<std::size_t>(16, static_cast<std::size_t>(std::sqrt(static_cast<double>(n_samples)) / 3.0));
}

}  // namespace ffcl::benchmark
